SourceCode.Declaration:
[
    SRSReportParameterAttribute(classStr(AVAHandoverDocContract)),
    SRSReportQueryAttribute(queryStr(AVAHandoverDocQuery))
]
public class AVAHandoverDocDP extends SRSReportDataProviderPreProcessTempDb
{
    AVAHandoverDocTmp   tmpTable;
    AVAHandoverDocTable handoverDocTable;
    AVAHandoverDocLine  handoverDocLine;

    Set                     handoverDocTables;

}

Method.Source:
[
    SRSReportDataSetAttribute(tableStr(AVAHandoverDocTmp))
]
public AVAHandoverDocTmp getTmpTable()
{
    select tmpTable;
    return tmpTable;
}

public void init()
{
    handoverDocTables  = new Set(Types::Int64);
}

public void updateHandoverDocTable()
{
    SetEnumerator         setEnumerator;
    AVAHandoverDocTable   localHandoverDocTable;
    Object                  _contract;

    _contract = this.parmDataContract();

    ttsBegin;

    setEnumerator = handoverDocTables.getEnumerator();

    while (setEnumerator.moveNext())
    {
        localHandoverDocTable = AVAHandoverDocTable::findByRecId(setEnumerator.current(), true);

        localHandoverDocTable.Printed = NoYes::Yes;
        localHandoverDocTable.update();
    }

    ttsCommit;
}

[SysEntryPointAttribute]
public void processReport()
{
    Query                               query;
    QueryRun                            queryRun;

    this.init();

    query                               = this.parmQuery();
    queryRun                            = new QueryRun(query);

    while (queryRun.next())
    {
        handoverDocTable    =   queryRun.get(tableNum(AVAHandoverDocTable));

        this.insertIntoTmpTable_Header();

        while select handoverDocLine
            where handoverDocLine.HandoverDocId == handoverDocTable.RecId
        {
            this.insertIntoTmpTable_Line();

        }

        handoverDocTables.add(handoverDocTable.RecId);
    }

    this.updateHandoverDocTable();
}

public void insertIntoTmpTable_Header()
{
    tmpTable.ReportElements     = AVAHandoverDocDataType::Basic;

    tmpTable.CustName           = handoverDocTable.displayCustName();
    tmpTable.DlvModeId          = handoverDocTable.displayDlvModeId();
    tmpTable.InventLocationId   = handoverDocTable.InventLocationId;
    tmpTable.LoadId             = handoverDocTable.LoadId;
    tmpTable.HeaderNotes        = handoverDocTable.displaySalesTableInfoField3();
    tmpTable.OrderNum           = handoverDocTable.OrderNum;
    tmpTable.ShipmentId         = handoverDocTable.ShipmentId;
    tmpTable.WMSLocationId      = handoverDocTable.WMSLocationId;

    this.avaCreateShipmentQRCode();

    tmpTable.insert();
}

public void insertIntoTmpTable_Line()
{
    tmpTable.ReportElements         = handoverDocLine.DataType == AVAHandoverDocDataType::Picked ? AVAHandoverDocDataType::Picked : AVAHandoverDocDataType::Open;

    tmpTable.CustName               = handoverDocTable.displayCustName();
    tmpTable.DlvModeId              = handoverDocTable.displayDlvModeId();
    tmpTable.InventLocationId       = handoverDocTable.InventLocationId;
    tmpTable.LoadId                 = handoverDocTable.LoadId;
    tmpTable.HeaderNotes            = handoverDocTable.displaySalesTableInfoField3();
    tmpTable.OrderNum               = handoverDocTable.OrderNum;
    tmpTable.ShipmentId             = handoverDocTable.ShipmentId;
    tmpTable.WMSLocationId          = handoverDocTable.WMSLocationId;

    tmpTable.InventQty              = handoverDocLine.InventQty;
    tmpTable.InventTransId          = handoverDocLine.InventTransId;
    tmpTable.ItemId                 = handoverDocLine.ItemId;
    tmpTable.InventUnitId           = handoverDocLine.inventTable().inventUnitId();
    tmpTable.Weight                 = handoverDocLine.displayWeight();
    tmpTable.WeightUnitId           = handoverDocLine.displayWeightUnitSymbol();
    tmpTable.LineNum                = handoverDocLine.LineNum;
    tmpTable.PickedQty              = handoverDocLine.PickedQty;
    tmpTable.TargetLicensePlateId   = handoverDocLine.TargetLicensePlateId;
    tmpTable.WorkId                 = handoverDocLine.WorkId;

    tmpTable.insert();
}

public void avaCreateShipmentQRCode()
{
    EFDocQRCode_BR qrCode;

    qrCode  = new EFDocQRCode_BR();

    tmpTable.ShipmentQRCode         = qrCode.generateQRCode(tmpTable.ShipmentId);
}
